import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { ChevronDown, Search, Menu, X } from 'lucide-react';
import LoginModal from './LogMedal';

export default function Header() {
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [selectedLocation, setSelectedLocation] = useState('Lefkosia');
  const [searchQuery, setSearchQuery] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);

  const navigate = useNavigate();

  const toggleDropdown = () => setIsDropdownOpen(!isDropdownOpen);
  const toggleMobileMenu = () => setIsMobileMenuOpen(!isMobileMenuOpen);
  const handleSearch = (e) => {
    e.preventDefault();
    navigate(`/search?query=${searchQuery}`);
  };
  const handleLocationChange = (location) => {
    setSelectedLocation(location);
    setIsDropdownOpen(false);
  };
  const toggleModal = () => setIsModalOpen(!isModalOpen);

  return (
    <header className="bg-white shadow-md">
      <div className="container mx-auto px-4 py-4 flex items-center justify-between">
        {/* Logo */}
        <div className="flex items-center">
          <Link to="/">
            <img src="/k1.jpeg" alt="Logo" className="w-28" />
          </Link>
        </div>

        {/* Search Bar */}
        <div className="hidden md:flex flex-grow mx-6">
          <form onSubmit={handleSearch} className="flex items-center w-full">
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Find Cars, Mobile Phones and more..."
              className="flex-grow p-2 border rounded-l-md focus:outline-none"
            />
            <button
              type="submit"
              className="p-2 bg-red-500 text-white rounded-r-md hover:bg-red-600"
            >
              <Search size={20} />
            </button>
          </form>
        </div>

        {/* Mobile Menu & Options */}
        <div className="flex items-center space-x-4">
          <button
            onClick={toggleMobileMenu}
            className="md:hidden text-gray-600 hover:text-gray-800"
          >
            {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
          <button
            onClick={toggleModal}
            className="hidden md:block text-gray-600 hover:text-gray-800"
          >
            Login
          </button>
          <Link
            to="/sell"
            className="hidden md:block bg-red-500 text-white px-4 py-2 rounded-md hover:bg-red-600"
          >
            Sell
          </Link>
        </div>
      </div>

      {/* Location Dropdown */}
      {isDropdownOpen && (
        <div className="absolute top-16 left-4 bg-white shadow-lg rounded-md w-48 z-50 border">
          <ul>
            {['Lefkosia', 'Magusa', 'Girne', 'Guzelyurt', 'Lefke', 'Iskele'].map((location) => (
              <li
                key={location}
                onClick={() => handleLocationChange(location)}
                className="px-4 py-2 hover:bg-gray-100 cursor-pointer"
              >
                {location}
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="absolute inset-0 bg-white z-50 flex flex-col p-4">
          <button
            onClick={toggleMobileMenu}
            className="self-end mb-4 text-gray-600 hover:text-gray-800"
          >
            <X size={24} />
          </button>
          <Link to="/sell" className="mb-4 text-red-500 hover:underline">
            Sell
          </Link>
          <button onClick={toggleModal} className="text-red-500 hover:underline">
            Login
          </button>
        </div>
      )}

      {/* Login Modal */}
      {isModalOpen && <LoginModal onClose={toggleModal} />}
    </header>
  );
}
